const router = Router();

router.get('/', authMiddleware, async (req: Request, res: Response) => {
  try {
    const payments = await paymentService.getPaymentsByUser(req.user.id);
    res.json(payments);
  } catch (error) {
    logger.error('Error fetching payments:', error);
