    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      const payment = await paymentService.createPayment({
        ...req.body,
        userId: req.user.id,
      });
      res.status(201).json(payment);
    } catch (error) {
